from pwn import *
import string
import time

context.log_level = 'error'

def connect_to_server():
    for port in [8040, 8041, 8042, 8043]:
        try:
            conn = remote('crypto.chal.csaw.io', port)
            return conn
        except:
            continue
    raise Exception("Could not connect to any server port")

def get_encrypted_length(payload):
    for _ in range(3):  # Try up to 3 times
        try:
            conn = connect_to_server()
            conn.recvuntil(b"Encrypting service\n", timeout=2)
            conn.sendline(payload.encode())
            response = conn.recvline(timeout=2)
            conn.close()
            if response:
                return len(response.strip())
        except:
            if conn:
                conn.close()
            time.sleep(0.5)
            continue
    return None

def find_next_char(known_prefix, attempts=3):
    possible_chars = string.ascii_lowercase + '_'
    results = {}

    # Test each character multiple times to ensure reliability
    for _ in range(attempts):
        for c in possible_chars:
            # Create a payload that would compress well if the guess is correct
            test_str = known_prefix + c
            padding = "A" * (20 - len(test_str))  # Ensure minimum 20 chars
            test_str = test_str * 3 + padding

            length = get_encrypted_length(test_str)
            if length:
                results[c] = results.get(c, []) + [length]
            time.sleep(0.1)

    # Average the results for each character
    avg_results = {c: sum(lengths)/len(lengths) for c, lengths in results.items() if lengths}
    if not avg_results:
        return None

    return min(avg_results.items(), key=lambda x: x[1])[0]

def main():
    known_key = ""
    max_attempts = 30

    print("Starting attack...")

    for i in range(max_attempts):
        print(f"\rCurrent key: {known_key}", end="", flush=True)
        next_char = find_next_char(known_key)
        if next_char:
            known_key += next_char
        else:
            break

    print(f"\nFinal key found: {known_key}")
    return known_key

if __name__ == "__main__":
    try:
        key = main()
        if key:
            print("Submitting flag...")
            submit_flag(key)
    except KeyboardInterrupt:
        print("\nAttack interrupted by user")
